<?php
$sc=fn($v)=>$v===null?'<span class="muted">—</span>':'<span class="sc sc-'.($v>=75?'g':($v>=50?'a':'r')).'">'.(int)$v.'</span>';
if(!$leads):?><div class="empty"><?=icon('users')?><h4>No leads here yet</h4><p><?=e($emptyMsg??'Leads will appear as they are found.')?></p></div><?php else:?>
<div class="tw"><table class="tbl lt"><thead><tr><?php if(!empty($selectable)):?><th class="cb"><input type="checkbox" data-all></th><?php endif?><th>#</th><th>Business</th><th>Contact</th><th>Rating</th><th title="Website score">Web</th><th title="Google Maps score">Maps</th><th>Stage</th><th>Email</th><th>WhatsApp</th><th>Replied</th><th></th></tr></thead><tbody>
<?php foreach($leads as $l):?><tr data-id="<?=$l['id']?>" data-stage="<?=e($l['stage'])?>"><?php if(!empty($selectable)):?><td class="cb"><input type="checkbox" name="ids[]" value="<?=$l['id']?>" form="bulk"></td><?php endif?><td class="muted"><?=$l['position']?></td><td class="biz"><a href="<?=url('lead',['id'=>$l['id']])?>"><b><?=e($l['name'])?></b></a><small><?=e($l['category'])?><?=$l['city']?' · '.e($l['city']):''?></small><?php if($l['website']):?><a class="wl" href="<?=e(Scraper::norm($l['website']))?>" target="_blank" rel="noopener"><?=icon('globe')?><?=e(mb_strimwidth(preg_replace('~^https?://(www\.)?|/$~','',$l['website']),0,34,'…'))?></a><?php else:?><span class="bdg bdg-red sm">No website</span><?php endif?></td><td class="ctc"><?php if($l['phone']):?><span><?=icon('phone')?><?=e($l['phone'])?><?php if($l['phone_source']==='website'):?><em class="src" title="Found on website">web</em><?php endif?></span><?php endif?><?php if($l['email']):?><span><?=icon('mail')?><?=e($l['email'])?></span><?php endif?><?php if(!$l['phone']&&!$l['email']):?><span class="muted">—</span><?php endif?></td><td><?=$l['rating']?'<b>'.e($l['rating']).'</b>★ <small class="muted">('.(int)$l['reviews'].')</small>':'<span class="muted">—</span>'?></td><td><?=$sc($l['web_score'])?></td><td><?=$sc($l['map_score'])?></td><td><?=badge($l['stage'])?></td><td><?=chbadge($l['email_status'])?></td><td><?=chbadge($l['wa_status'])?></td><td><?=$l['replied_at']?'<span class="bdg bdg-green">'.icon('check').e(ucfirst($l['replied_via'])).'</span>':'<span class="muted">—</span>'?></td><td class="act"><a class="ib" href="<?=url('lead',['id'=>$l['id']])?>" title="Open journey"><?=icon('eye')?></a></td></tr><?php endforeach?>
</tbody></table></div><?php endif;
